import type { Section } from "../hotels";

/**
 * Individually commissioned additions. These are deliberately stored by
 * property rather than generated: each claim and caveat belongs to the hotel
 * named by its key.
 */
export const individualReviewAdditions: Record<string, Section[]> = {
  "aman-tokyo": [
    { heading: "Otemachi from above", body: [
      "The location is central but psychologically removed. Otemachi is the capital's corporate core, useful for the Imperial Palace and connected directly to several subway lines, yet it largely empties after office hours. That makes the hotel exceptionally good at retreat and less convincing for travellers who want to fall out of the lobby into late-night alleys. Ginza, Nihonbashi and Marunouchi are close; Shibuya and Shinjuku require an intentional journey.",
      "Kerry Hill Architects made that remove productive. The 33rd-floor arrival is organised around a monumental lantern-like volume of washi, while stone, timber and water establish the proportions of a ryokan without copying one. Views are not decorative extras here. Palace gardens, office towers and, on clear western horizons, Mount Fuji continually alter the rooms, so orientation deserves as much attention as category."
    ]},
    { heading: "A spa large enough to change the stay", body: [
      "Aman's official figures put the wellness space at 2,500 square metres across two floors, with eight treatment rooms, Japanese-style baths, steam rooms, studios and a 30-metre indoor pool. The scale matters after a long flight: this is not a basement spa appended to a city hotel, but one of the principal reasons to book it. The pool's long black line and wall of sky can reset a body clock more persuasively than another afternoon coffee.",
      "Dining now stretches beyond the lounge. Arva serves southern Italian cooking; Musashi is an intimate Edomae sushi counter; La Pâtisserie operates at the tower's base; afternoon tea animates the vast lobby. That breadth is welcome, though the hotel's quietest hours are early morning and late evening, once non-resident diners have gone. Reserve Musashi well ahead and eat outside at least once: Tokyo's greatest luxury remains the city itself."
    ]},
    { heading: "What to book, and what to accept", body: [
      "All 84 accommodations are suites, with entry categories beginning at a remarkable 71 square metres. Deluxe Suites face west for sunset; Garden View Suites occupy the highest floor and look toward the Imperial Palace; corner Panorama Suites trade still greater expense for a wider arc of city. If Mount Fuji matters, request rather than expect it—weather, haze and orientation control the view.",
      "The cost is formidable and the atmosphere can verge on reverential. Travellers seeking a lively bar, a neighbourhood scene or highly expressive Japanese food on every floor may find the composure too complete. For design, space, bathing and the rare sensation of hearing almost nothing above central Tokyo, however, Aman remains the benchmark."
    ]}
  ],
  "the-ritz-paris": [
    { heading: "One hotel, several versions of Paris", body: [
      "The Ritz is not a single mood. Bar Vendôme behaves like a handsome Parisian brasserie beneath its glass roof; Salon Proust turns tea into an upholstered ritual; the Grand Jardin supplies green silence behind Place Vendôme; Bar Hemingway compresses the mythology into a small, coveted room. The fashionable mistake is to spend the stay chasing the famous bar stool. The wiser pleasure is to move among these different registers and notice how little of the hotel feels like a corridor between them.",
      "Espadon has also entered a new chapter under chef Eugénie Béziat, whose cooking draws on Mediterranean and African memories rather than reenacting Escoffier. It currently holds a Michelin star. That evolution is important: a hotel so burdened by legend survives only by allowing new talent to alter the conversation. Dinner requires planning; a spontaneous lunch at Bar Vendôme may reveal the house more naturally."
    ]},
    { heading: "The room hierarchy is unusually consequential", body: [
      "The 142 keys vary from 35-square-metre Superior Rooms to historic Prestige Suites with names and narratives of their own. A lower category still brings marble, fine fabrics and serious housekeeping, but outlook changes everything. Place Vendôme carries theatre and traffic; the Grand Jardin offers romance and relative calm; certain high rooms frame the Opéra or Eiffel Tower. Ask for a view in plain language rather than trusting a category name to explain it.",
      "The famous Coco Chanel connection can obscure equally compelling suites devoted to Hemingway, Chopin, Windsor and other former guests. Unless the biography is the reason for travelling, space and orientation should win. The most expensive room is not automatically the most comfortable for a particular stay, and heavily decorated historic suites can feel more ceremonial than restful."
    ]},
    { heading: "The case for staying—and the case against", body: [
      "Service is formal but should never feel stiff; the best version anticipates without narrating its anticipation. The Ritz Club & Spa, with its painted-sky pool, sauna and steam room, gives rainy afternoons a persuasive destination. Yet the address can become its own world, and guests who never leave risk experiencing Paris as upholstery. The Tuileries, Palais Royal and Louvre are close enough to restore proportion before breakfast.",
      "Value here is emotional rather than mathematical. Newer palace hotels offer larger entry rooms and more visible technology. The Ritz offers the original grammar of grand hospitality, maintained at extraordinary cost. Book it for an anniversary, a first or final night, or because Place Vendôme has occupied the imagination for years—not because a ranking said it was compulsory."
    ]}
  ],
  "marina-bay-sands": [
    { heading: "A resort the size of a district", body: [
      "Marina Bay Sands cannot be judged by boutique-hotel criteria. The three towers feed into a convention centre, casino, theatre complex and luxury mall; the ArtScience Museum sits beside them like an open hand. At peak periods the ground floors move with the density of an airport. The achievement is not intimacy but legibility: lifts, check-in zones and staff turn enormous numbers of people into a system that usually works.",
      "That scale creates two experiences. Public areas are destinations for the city and can feel relentlessly exposed; guest-only spaces, especially the SkyPark infinity pool, restore a measure of privilege. Anyone expecting a secluded urban retreat will resent the crowds. First-time visitors who want Singapore's skyline, dining and spectacle assembled in one address may find the energy exhilarating."
    ]},
    { heading: "The renewed room question", body: [
      "The room inventory has been undergoing a major reinvention, making tower, collection and renovation status essential booking questions. High floors facing the bay deliver the famous composition of downtown towers and Gardens by the Bay; city-facing rooms exchange that postcard for the urban grid. The newer rooms are warmer and more residential than the original polished interiors, but distances from lift to bed can still be substantial.",
      "Do not book solely for pool access and then choose the cheapest view without thought. The pool is busiest at the photogenic edges and weather can close the sky in minutes. A good room preserves the reason for staying after the swim is over. Club or premium privileges may improve breakfast and arrival, but current inclusions should be checked against the exact rate rather than inferred from an old review."
    ]},
    { heading: "How to use the roof", body: [
      "Go to the infinity pool twice: once soon after opening, when the water is calm enough to see the architecture, and once at dusk, when office lights begin replacing the sun. The edge is not a private wilderness and the photograph will require patience. Step away from the central section and the experience becomes less performative; a long swim can still be found beneath the observation decks.",
      "Below, the danger is never having to leave. That convenience is useful on a short stopover and impoverishing on a longer visit. Cross the bay on foot, eat in a hawker centre and spend a morning in a neighbourhood where the building disappears from view. Marina Bay Sands is an extraordinary way to understand Singapore's ambition, but not a substitute for understanding Singapore."
    ]}
  ],
  "burj-al-arab": [
    { heading: "The suite is the basic unit", body: [
      "All 202 accommodations are duplex suites, so even the entry experience involves a staircase, two levels and a view framed by the sail-shaped structure. The arrangement feels grand on arrival and can be mildly inconvenient by the third trip upstairs for a charger. Fabrics, colour and gold are intentionally emphatic. Travellers who prefer pale oak and concealed technology should not expect the building to apologise for being itself.",
      "Suite position affects whether the view opens toward the Gulf or the Dubai coast, while higher categories add scale faster than most parties can use it. A butler service supports each floor, but the value is not in requesting theatrics; it is in having restaurant, transfer and wardrobe problems solved without friction. Ask about layout and accessibility before paying for square footage, particularly if stairs are difficult."
    ]},
    { heading: "Water, restaurants and controlled access", body: [
      "The Terrace extends into the Gulf with pools, cabanas and a man-made beach platform, giving resident guests a calmer daytime counterpoint to the atrium. Because the Burj is an attraction as well as a hotel, restaurants and organised visits bring non-residents through controlled zones. The building never becomes conventionally private; it becomes selectively accessible.",
      "Dining is part of the architecture. Al Muntaha occupies the upper levels; Al Mahara builds a room around a vast aquarium; other venues use the atrium, sea and skyline as scenery. Prices reflect the address before the first course arrives. Choose one meal for setting and another for cooking, then compare the final bill with Dubai's deep independent restaurant scene."
    ]},
    { heading: "A twenty-first-century period piece", body: [
      "Tom Wright's building opened in 1999 and quickly became a global shorthand for Dubai. Its helipad, atrium and unsupported-sail profile were engineered as symbols, not neutral containers. That makes the hotel more interesting now than a merely new resort: it records the moment the city decided that architecture could function as international advertising.",
      "The trade-offs follow directly. Walkability is negligible, visual restraint nonexistent and the atmosphere can feel choreographed. Yet a one- or two-night stay delivers something few luxury hotels still manage—a genuine sense of occasion. Pair it with a quieter desert or beach property and the excess becomes sharper, stranger and more enjoyable."
    ]}
  ],
  "la-mamounia": [
    { heading: "Gardens as a way of keeping time", body: [
      "The estate changes by hour. In the morning, birds and gardeners have the advantage; after lunch, the pool and shaded paths absorb the heat; toward evening, the Koutoubia rises beyond palms and the public rooms begin to fill. The grounds include mature olive, citrus and palm trees as well as a substantial kitchen garden. This is not landscaped scenery viewed from a terrace but a second plan of the hotel, with paths that reward repetition.",
      "That space distinguishes La Mamounia from even the finest medina riads. It also creates distance. A room at one end of the building and breakfast at the pool pavilion can involve a proper walk, and three private riads hidden in the gardens operate at an entirely different scale from the main house. Families and multi-generational groups should map daily routines before defaulting to the most romantic outlook."
    ]},
    { heading: "Rooms, riads and the importance of outlook", body: [
      "The official inventory divides 209 keys into 135 rooms, 71 suites and three riads. Standard rooms combine zouac-painted ceilings, mashrabiya screens, stone and zellige with contemporary comforts; some add balconies, while views range across gardens, pool, Hivernage and the Koutoubia. The category names alone do not communicate light or distance, so ask which direction the room faces and whether outdoor space matters more than height.",
      "The riads are 700-square-metre private houses with their own entrances, pools and terraces, intended for up to six guests. They offer concealment inside a famously public hotel but can isolate a short stay from the main building's energy. For most couples, a well-oriented room or suite keeps the essential balance: enough quiet to retreat, enough proximity to feel the institution at work."
    ]},
    { heading: "Four restaurants, two tea rooms and one necessary escape", body: [
      "The current restaurant line-up spans Moroccan cooking by Rachid Agouray, Italian food by Simone Zanoni, Asian dishes associated with Jean-Georges Vongerichten and the pool pavilion; Pierre Hermé shapes the tea rooms and pastry. The breadth makes sense for a palace hotel and reduces the danger of menu fatigue, though reservations and seasonal hours should be confirmed. Le Marocain is the meal most directly tied to place; the garden tea room is often the more memorable daytime ritual.",
      "The spa occupies 2,500 square metres with hammams, treatment rooms and heated indoor and outdoor pools. It can consume a day, but Marrakech should interrupt the cocoon. The medina begins beyond the gates, and the contrast between its density and the hotel's ordered gardens is central to the stay. La Mamounia is most persuasive as a base from which to enter the city, not as an alternative to doing so."
    ]}
  ],
  "the-plaza-new-york": [
    { heading: "Fifth Avenue outside, a landmark inside", body: [
      "The southeast corner of Central Park is one of the few New York addresses that needs no explanation. Step outside and the park, Fifth Avenue and Museum Mile pull in different directions; stay upstairs and the city arrives as treetops, horns and a slice of skyline. A park-facing room is expensive but conceptually complete. Interior and courtyard views retain the decoration while losing much of the reason to choose this particular building.",
      "The Plaza is also a condominium and retail complex, not a hotel occupying every inch of its château-like shell. That mixed-use reality helps explain the occasional disjunction between iconography and operation. Resident and visitor traffic, shops and afternoon-tea crowds all share the stage. Experienced guests use the quieter hotel entrances and allow extra time at peak hours rather than expecting a private-house arrival."
    ]},
    { heading: "Rooms built for old New York", body: [
      "Guest rooms lean into Louis XV furniture, crystal, patterned carpets and bathrooms bright with marble and gold-toned fittings. The aesthetic is literal and lavish rather than gently referential. Entry rooms can feel less expansive than their price suggests, while suites supply the kind of separate sitting space that makes room service and family travel far more comfortable. Study the floor plan, not merely the title.",
      "The hotel's most famous fictional resident still shapes the family offer, but Eloise-themed experiences should be planned rather than allowed to define every hour. Couples seeking a more adult rhythm should request a room away from family-heavy corridors and treat the Palm Court between services, when its stained-glass ceiling can be admired without an audience around every table."
    ]},
    { heading: "Tea, cocktails and the limits of nostalgia", body: [
      "Afternoon tea in the Palm Court is an institution and priced as one. Its value lies in the room, ritual and intergenerational theatre, not in discovering New York's most experimental pastry. The Champagne Bar faces Fifth Avenue and works better for an early drink when the windows still hold the park. For serious dinner, leave the building: Midtown's dining life is too broad to spend every meal under the same chandeliers.",
      "The Plaza succeeds when booked as a landmark with bedrooms, not measured against every newer luxury hotel amenity by amenity. It cannot supply downtown intimacy or contemporary minimalism. It can give a child a story, a first visitor an address they already know, and a returning New Yorker the peculiar pleasure of waking beside Central Park inside a piece of collective memory."
    ]}
  ],
  "belmond-hotel-caruso": [
    { heading: "Ravello changes the Amalfi bargain", body: [
      "Ravello sits inland and high above the water, so Caruso exchanges direct beach access for air, gardens and a horizon uncluttered by ferries. That is an excellent trade for travellers who find Positano's stairs and traffic exhausting, and the wrong one for anyone who wants to step from breakfast onto a boat. The hotel's complimentary shuttle and organised excursions soften the isolation; they do not eliminate the coast's slow logistics.",
      "The building grew from an eleventh-century palazzo and still carries fragments of fresco, vaulted rooms and old stone through its polished resort life. Terraces planted with lemon, olive and rose turn the property into a sequence rather than a single view. Even at full occupancy, a quiet bench or shaded path can usually be found away from the pool's camera-facing edge."
    ]},
    { heading: "The infinity pool is not the whole story", body: [
      "The famous pool seems to pour directly into sea and sky, an illusion strengthened by Ravello's elevation. It is genuinely beautiful, especially before breakfast and late in the day, but loungers and the most photogenic corners are finite. Guests who plan an entire stay around uninterrupted pool solitude in August are booking a photograph rather than an operating hotel.",
      "Belmond has developed La Piscina as a social hub around the water and reopened the main restaurant as Il Pantaleone, where Campanian ingredients and the terrace do most of the persuasive work. The kitchen garden supplies herbs and produce; local fishermen and farmers give the menu a necessary regional accent. Save one evening for Ravello itself, whose piazza becomes gentler after day visitors leave."
    ]},
    { heading: "Room advice and season", body: [
      "Rooms and suites vary with the old architecture. Sea-facing terraces are the prize; village or garden outlooks can be more private and considerably less costly. Villa Margherita, a separate two-suite residence with garden and private service, suits families or friends who want autonomy without giving up the hotel. Couples on a short stay should usually spend on outlook before square metres.",
      "Caruso is seasonal, and the best months are not automatically the hottest. Late spring brings gardens and long light without peak traffic; early autumn keeps the sea warm while restoring some breathing room. Weather can still close a pool day or complicate a boat. The hotel is strong enough to carry that disappointment—one reason it ranks above properties whose beauty exists only outdoors."
    ]}
  ],
  "singita-sabi-sand": [
    { heading: "First decide which Singita", body: [
      "'Singita Sabi Sand' describes a private reserve and several distinct ways to inhabit it. Ebony Lodge, the brand's founding property, sits among trees above the Sand River and was refreshed in 2024 with more canvas, glass and contemporary African art. Boulders Lodge uses stone, timber and the riverbank to feel earthier and more elemental. Castleton is a private-use farmhouse for families and groups. They share exceptional access to the same 45,000-acre landscape but not the same atmosphere.",
      "The choice should follow the party. Ebony welcomes children of all ages and its 12 suites each have a plunge pool; Boulders feels especially suited to couples; Castleton makes sense only when privacy and shared space justify exclusive use. Treating the lodges as interchangeable risks paying a remarkable rate for the wrong social rhythm."
    ]},
    { heading: "What the rate is really buying", body: [
      "Twice-daily game drives are only the visible portion. The higher cost supports small guest numbers, experienced field guides and trackers, a deep wine programme, food that can adapt to the day's movements and conservation work extending beyond the vehicle. Leopard sightings are frequent in Sabi Sand but never guaranteed; the quality test is whether a guide can make tracks, birds, trees and an apparently quiet hour compelling.",
      "A safari day starts before sunrise, pauses through the heat and returns to the bush in late afternoon. Ebony's suspended decks and glass-fronted suites make the middle hours part of the wildlife experience rather than an interval to fill. Elephants, monkeys and birds do not observe hotel boundaries. Guests follow staff instructions after dark because this is functioning habitat, not resort landscaping."
    ]},
    { heading: "Conservation claims deserve questions", body: [
      "Singita articulates a century-long purpose around biodiversity and neighbouring communities, working in South Africa through the Singita Lowveld Trust. The ambition is substantial, but responsible travellers should still ask how the particular stay contributes, what local partnerships are active and which activities create pressure. Sustainability is not proven by a reusable bottle; it is visible in land management, employment, procurement and the behaviour of vehicles at sightings.",
      "Four nights is the useful minimum for this investment. The private airstrip is about ten minutes from the lodges, with scheduled services limiting soft-sided baggage. A two-night dash can produce spectacular photographs but little understanding. Stay long enough for the landscape to become more than a list of animals, and the price begins to make a different kind of sense."
    ]}
  ],
  "hotel-cipriani-venice": [
    { heading: "Giudecca as an advantage", body: [
      "The Cipriani occupies the eastern end of Giudecca, separated from San Marco by a short hotel launch and an enormous change in mood. Boats run frequently, but every outing still acquires a threshold: walk to the pier, cross the basin, return on the hotel's rhythm. First-time visitors intent on dawn-to-midnight immersion may prefer to sleep in the historic centre. Repeat visitors often recognise the separation as the hotel's defining luxury.",
      "Three acres of garden, paths and low buildings make the property feel horizontal in a city of compressed lanes. The Olympic-sized saltwater pool is extraordinary partly because Venice offers so little open land. Daylight hours can disappear between water, tennis and the lagoon without a single church entered. That is either liberation or dereliction of tourist duty, depending on the trip."
    ]},
    { heading: "Palazzo or garden room?", body: [
      "Rooms in the main building use Venetian textiles, glass and painted furniture without disguising their resort purpose. Garden and lagoon outlooks lead to very different mornings; balconies are limited and worth confirming. Palazzo Vendramin, reached along the waterfront, offers a more residential atmosphere and some of the most expansive views back toward San Marco, with butler service for its suites.",
      "Old-building variation remains part of the charm. Floor plans, ceiling heights and distance from the main facilities differ, so a request such as 'quiet and close to the pool' is more helpful than asking for a generic upgrade. Families value the grounds and connecting possibilities; couples may prefer the privacy of the palazzo or a terrace facing the lagoon."
    ]},
    { heading: "Dinner after the day boats leave", body: [
      "Oro is the formal restaurant, while Il Porticciolo keeps lunch close to the lagoon and Bar Gabbiano anchors the pool. Names and chefs evolve, so current opening days should be checked, particularly at the edges of the season. Venice itself is the indispensable dining room. Use the launch for cicchetti and a late table, then return across black water after the day-trip crowds have vanished.",
      "The price buys a paradox unavailable elsewhere in the city: full-resort space with San Marco still in the frame. It also buys dependence on boats, a social pool and a degree of Belmond polish that can feel more international than Venetian. Come for three nights or more, when alternating city intensity with garden quiet becomes a rhythm rather than a commute."
    ]}
  ],
  "claridges-london": [
    { heading: "A hotel that has learned to add without erasing", body: [
      "Claridge's reputation rests on continuity, but recent years have involved enormous change beneath and above the Art Deco landmark: a multi-level subterranean excavation created a new spa and operational space while additional accommodation rose on the roof. The remarkable part is how little of that engineering announces itself at the front door. The black-and-white lobby remains instantly legible, and the staircase still produces the sensation of entering a particularly well-run private world.",
      "Individual rooms span several design eras. Restored Art Deco spaces sit beside suites shaped by contemporary designers, and the contrast is more interesting than forced uniformity would be. Guests should inspect the exact category photographs. Some classic rooms prioritise proportion and craftsmanship over the latest residential fashion; newer suites may feel brighter and more architectural."
    ]},
    { heading: "The public rooms each keep their own time", body: [
      "Afternoon tea in the Foyer & Reading Room remains the signature ritual, accompanied by musicians and a service choreography refined over generations. It is formal, lengthy and booked well ahead. Claridge's Restaurant handles the grand all-day appetite; the Fumoir is darker and more secretive; the Painter's Room is small enough for a cocktail to feel like an appointment. Choose according to mood rather than trying to complete a checklist.",
      "Mayfair supplies excellent alternatives within minutes, which makes eating every meal inside unnecessary. Breakfast, however, is a useful test of the house. The room should feel effortless before the day's theatre begins, and staff should know when to converse and when a guest needs silence. Claridge's greatest asset is not silver or history but this calibrated reading of people."
    ]},
    { heading: "The new spa, and the old bargain", body: [
      "The Claridge's Spa brings Japanese references, warm stone, treatment rooms and a swimming pool into the excavated levels below the hotel. Its hush is contemporary rather than clubby, giving the building a proper retreat for the first time. Access and treatment availability should be confirmed with the room rate; the spa is now important enough to shape a rainy London day.",
      "No Mayfair grand dame is a value proposition in the ordinary sense. Entry rooms can be smaller than newer competitors, traffic complicates arrivals and the public rooms attract non-residents. Claridge's earns its premium through character and service memory. If the preferred luxury is space alone, look elsewhere. If it is the feeling that a large institution has noticed precisely how you like to live, the old secret remains intact."
    ]}
  ],
  "hotel-du-cap-eden-roc": [
    { heading: "Three addresses within one legend", body: [
      "The name disguises a small estate. The nineteenth-century Hôtel du Cap occupies the main house amid Aleppo pines; Eden-Roc sits lower at the water's edge; private villas offer the most complete seclusion. The choice changes the stay. Main-house rooms retain the ceremony of the grande dame and a daily descent toward the sea, while Eden-Roc places saltwater, cabanas and restaurants closer to the door.",
      "Rooms favour Riviera classicism—pale fabrics, floral notes, marble and framed Mediterranean light—rather than experimental design. Exact outlook matters enormously. A sea view over the gardens can justify a smaller room; a larger category without outdoor space may feel less connected to Cap d'Antibes. Ask about building, floor, balcony and walking distance before comparing square metres."
    ]},
    { heading: "The coast is the amenity", body: [
      "The famous saltwater pool was blasted into basalt above the sea in 1914 and remains the visual centre of Eden-Roc. It is complemented by ladders into open water, diving boards, cabanas and boats, not a conventional sandy beach. Swimmers should understand sea state and access; families with young children may spend more time at the pool than the photographs of rocky glamour imply.",
      "Lunch by the water is one of the Riviera's great rituals, but the hotel attracts a visible social world during Cannes and high summer. Privacy then becomes an expensive and carefully managed commodity. Late May, June and September offer a gentler version, with warm light and fewer reasons for every table to scan the room."
    ]},
    { heading: "What the mythology leaves out", body: [
      "Fitzgerald, film stars and festival parties have supplied a century of copy, yet the useful test is ordinary operation: a boat organised correctly, breakfast arriving while it is still hot, a favourite cabana remembered, a damp swimsuit returned before dinner. At this price, heritage cannot excuse inconsistency. Guests should also expect seasonal restaurant schedules and confirm which waterfront facilities are open at the beginning and end of the season.",
      "Antibes is close, Cannes farther and road traffic unpredictable. The property works best when several days are surrendered to it rather than treated as a base for constant touring. Book for sea access, gardens and a very specific old-Riviera social grammar. If the wish is barefoot informality or contemporary restraint, the legend may become an obligation rather than a pleasure."
    ]}
  ],
  "badrutts-palace-st-moritz": [
    { heading: "Winter and summer are different hotels", body: [
      "In winter, the frozen lake becomes a white public square for polo, racing and long crossings, while Corviglia's lifts and pistes organise the day. Summer replaces the theatre with hiking, sailing and high-altitude light reflected off open water. Badrutt's belongs to both seasons, but its social temperature changes: winter is dressed, compressed and ceremonial; summer reveals terraces, valley air and a less competitive version of the Engadine.",
      "The lake view is worth understanding before arrival. Rooms on that side look over one of the Alps' defining panoramas; village-facing categories place more attention on the room itself. Historic architecture creates variation in size, ceiling and route to the lifts. Families should ask about connecting plans, while skiers should value equipment logistics and shuttle timing as highly as decorative category."
    ]},
    { heading: "A palace with a small town inside", body: [
      "The public rooms move from dark timber and portraits to brighter contemporary interventions, with enough restaurants and bars to make the hotel self-contained in bad weather. Le Restaurant carries the formal grand-hotel ritual; Chesa Veglia, in a farmhouse across the road, is the more atmospheric evening; King's Social House supplies nightlife. Seasonal concepts and chef partnerships change, so reservations should be built after current opening dates are confirmed.",
      "The spa and indoor pool matter more than brochure luxuries at 1,800 metres. So does the practical choreography of boots, children and changing weather. Badrutt's succeeds when staff make this complexity disappear, preserving the illusion that a mountain holiday consists only of choosing lunch. The busy lobby at peak weeks is the price of that social world, not a failure of it."
    ]},
    { heading: "Know the St Moritz bargain", body: [
      "This is not a village inn enlarged by affection. It is a seasonal palace whose rates, dress codes and restaurant bills reflect an international winter circuit. Guests looking for contemporary alpine minimalism or immediate ski-in access have sharper alternatives. The Palace offers history, lake position and a community of repeat visitors who treat its calendar as tradition.",
      "Stay at least four nights; shorter visits are consumed by transfers and acclimatisation. The Engadine's dry altitude can surprise, so begin gently and drink more water than the bar menu suggests. When the weather closes, accept the hotel's scale. When the sun appears, leave it—the landscape outside is the source of every story the Palace tells indoors."
    ]}
  ],
  "peninsula-hong-kong": [
    { heading: "The original building or the tower", body: [
      "The 1928 building carries the grand stair, colonnaded lobby and most of the emotional history; the 1994 tower rises above it with broader harbour views and a more contemporary vertical rhythm. Neither is automatically superior. Heritage rooms feel closer to the ceremony downstairs, while tower rooms can turn Victoria Harbour into a moving wall of ferries, weather and light.",
      "Peninsula's in-room technology has long been developed by the group itself, and the best systems make curtains, lighting and communication intuitive across languages. Technology ages faster than marble, however. Guests should judge whether controls disappear into the stay rather than awarding points for the number of buttons. Room orientation and glazing matter more than novelty on a city night."
    ]},
    { heading: "A lobby that belongs to Hong Kong", body: [
      "Afternoon tea beneath the lobby's high ceiling is famous and frequently queued. It is also public theatre, with music, pageboys and a constant exchange between hotel and city. Residents who want the room at its best should pass through early, before service begins, then return for tea only if the ritual itself appeals. There are quieter ways to eat well in the building.",
      "Gaddi's holds the old-school French dining room; Felix, designed by Philippe Starck, occupies the top floor; Spring Moon interprets Cantonese tradition in an Art Deco setting. The collection allows a stay to move across eras, but Hong Kong's restaurants are too important to ignore. One formal hotel dinner is sufficient; let the remaining meals pull you through Kowloon and across the harbour."
    ]},
    { heading: "Arrival theatre and practical value", body: [
      "The Peninsula green Rolls-Royces are symbols, but the more useful luxury is the hotel's Tsim Sha Tsui position beside the waterfront and MTR. Star Ferry crossings place Central within a journey that still feels romantic; museums and the promenade are walkable. Road transfers become less attractive when harbour traffic thickens, no matter how polished the car.",
      "The indoor pool and spa provide real refuge from humid summers, while high service ratios support the hotel's formal style. Yet public crowds and the density of Kowloon prevent total seclusion. Book for heritage, harbour and a staff culture that has learned to translate ceremony into efficiency. For a quieter residential mood, look to Hong Kong Island."
    ]}
  ],
  "soneva-fushi-maldives": [
    { heading: "Beach villa or overwater retreat", body: [
      "Soneva Fushi built its identity in the jungle, where beach villas disappear behind dense foliage and open directly onto sand. The later overwater villas add long decks, retractable bedroom roofs and slides into the lagoon. They are spectacular but represent a different idea of the island. Families often value the private gardens and direct beach play of the original villas; couples chasing horizon and water access may prefer the newer structures.",
      "Villa sizes are unusually generous and now extend to multi-bedroom residences of almost estate scale. More space can also mean longer bicycle rides and a diluted sense of intimacy. Ask which side of Kunfunadhoo best suits the season, swimming and sunset, then choose the smallest villa that comfortably fits the group. Privacy and shoreline condition matter more than a surplus bedroom."
    ]},
    { heading: "A resort with too much to do", body: [
      "The barefoot premise is simple; the programme is not. The Den is a serious children's world, the observatory has resident astronomers, the glass studio turns discarded bottles into objects, Aquaterra works on coral restoration and marine research, and visiting chefs, athletes and specialists rotate through the Soneva Stars calendar. The risk is scheduling wonder until the island feels like a summer camp with butler service.",
      "Each villa has a Barefoot Butler, best used to create spacious days rather than full ones. One reef trip, one evening at the observatory and one creative session can anchor a stay. The unprogrammed hours—cycling a sandy path, opening the chocolate room, watching fruit bats cross the canopy—are the experiences most distinct from a conventional Maldives resort."
    ]},
    { heading: "Read the dining plan before arrival", body: [
      "More than ten dining concepts range from Fresh in the Garden above the organic beds to Out of the Blue over the water, intimate sushi, fire cooking and free-access rooms devoted to chocolate, ice cream and cheese. This breadth solves the private-island problem of repetition. It also creates a complicated bill: half- and full-board plans cover selected restaurants and food credits, while drinks and certain experiences remain outside them.",
      "Transfers, meals and special dinners should be priced before comparing Soneva with a simpler all-inclusive. Sustainability claims also deserve detail. The resort designs around mature vegetation, produces water and reworks waste, but long-haul arrivals and large air-conditioned villas still carry costs. What distinguishes Soneva is not purity; it is the willingness to make those systems visible and invite guests into the questions."
    ]}
  ],
  "oberoi-udaivilas-udaipur": [
    { heading: "A new palace with a disciplined plan", body: [
      "Udaivilas opened in 2002 on former hunting grounds across Lake Pichola from Udaipur's historic core. Its domes, courtyards, fountains and hand-painted interiors quote Mewar architecture, but the building is organised as a resort: rooms reach gardens and pools easily, service routes disappear and the arrival by boat turns the City Palace into part of the approach. It is theatrical, yet the theatre has practical intelligence.",
      "The grounds spread across roughly 30 acres, with wildlife and planted gardens creating distance between guests. That space is restorative after the old city's lanes and mildly isolating if every meal or museum requires transport. The lake crossing is the memorable arrival, not a permanent shuttle to all plans; ask the concierge how boats and cars operate at the exact hour of a reservation."
    ]},
    { heading: "Pool access changes the room", body: [
      "Premier Rooms are already generous, with window seats, marble bathrooms and terraces. The coveted semi-private pool rooms open onto long shared water rather than individual plunge pools, creating an enchanting blue threshold and less privacy than the phrase 'pool access' can imply. Couples should ask how many rooms share the stretch; families must understand supervision and door security.",
      "Lake views, garden position and walking distance produce meaningful variation. Higher suites add separate rooms and more ceremony, but a well-placed pool room often delivers the most distinctive experience. Udaipur's light is directional and seasonal; west-facing views can be magnificent at sunset and warmer through the afternoon."
    ]},
    { heading: "How to balance resort and city", body: [
      "The restaurants cover international and Indian menus, with dinner often staged through music, candles and reflections on water. The setting carries a meal a long way, but the best stay also eats in town and spends time inside the City Palace rather than admiring it only across the lake. Two resort days and one city-heavy day create a better three-night rhythm than constant half-day excursions.",
      "This is a natural honeymoon hotel and an easy multi-generational choice because the service is protective and the grounds complete. It is less suited to travellers who want independent street life outside the gate. Book for architectural romance, pool hours and an operation polished enough to make a newly built palace feel emotionally credible."
    ]}
  ],
  "park-hyatt-tokyo": [
    { heading: "The post-restoration hotel", body: [
      "The most important current fact is that Park Hyatt Tokyo is no longer the gently ageing time capsule described by years of reviews. It closed for 19 months and reopened in December 2025 after the most comprehensive restoration in its history. Jouin Manku refreshed all rooms and suites, restored public spaces and reshaped dining while protecting the vertical procession and quiet material confidence that made the 1994 hotel influential.",
      "That work changes the bargain. Updated technology, fabrics and bathrooms now sit inside John Morford's original architectural logic, rather than replacing it with a new visual identity. Returning guests will notice sharper comfort and altered details; first-timers still encounter the cinematic sequence of lift, library, distant piano and Tokyo laid out below. Nostalgia has been serviced, not embalmed."
    ]},
    { heading: "Rooms and the tyranny of orientation", body: [
      "The hotel occupies floors 39 to 52 of Kenzo Tange's Shinjuku Park Tower. Rooms remain large for Tokyo, with deep baths, dressing space and windows broad enough to turn weather into entertainment. West-facing categories offer the possibility of Mount Fuji; other orientations deliver denser city geometry. A mountain view is never guaranteed, even from the correct side, so book the exposure and treat visibility as weather's gift.",
      "The vertical layout means every outing involves several transitions, and Shinjuku Station is not directly under the building. Taxis simplify evenings; the walk through west Shinjuku is manageable but not romantic. Guests who want izakaya and rail platforms at the door should stay lower and closer. Here, altitude is both inconvenience and point."
    ]},
    { heading: "New York Grill without the film", body: [
      "New York Grill & Bar still occupies the 52nd floor, with live music, open kitchens and the skyline that made it famous. Girandole has returned under Alain Ducasse, and the Peak Lounge preserves the glass-roofed atrium as a place for tea and drinks. Current reservations, music charges and dress expectations should be checked; fame can make an apparently casual evening surprisingly procedural.",
      "Club on the Park, with its high pool and spa, remains essential to the jet-lag cure. The hotel is at its best when guests stop reenacting cinema and use it as designed: swim early, descend into Tokyo, then return for one late drink above the lights. The restoration gives that ritual another life without pretending 1994 never happened."
    ]}
  ],
  "amangiri-utah": [
    { heading: "The desert is not empty", body: [
      "Amangiri occupies 900 acres of the Colorado Plateau near the Arizona border, where rock, archaeological history and Navajo land make the landscape culturally as well as geologically complex. The architecture's sand-coloured concrete is powerful because it defers to those formations. Guides should give the scenery language and context, not present it as an unclaimed backdrop for luxury adventure.",
      "The central pool wraps a sandstone escarpment rather than replacing it, and paths move from highly controlled rooms into open desert within minutes. Twelve-plus miles of designated trails permit self-guided walks, while daily guided hikes are included in the stay. More ambitious via ferrata routes, slot-canyon visits, Lake Powell excursions and flights cost extra and require weather-aware planning."
    ]},
    { heading: "Choose a suite by light", body: [
      "The resort's 34 suites share stone floors, concrete walls, fireplaces and private outdoor space but face different landforms. Mesa categories are positioned for rose-gold sunsets; Desert Suites look across dunes and plateaus; pool suites trade still more money for water and a sky terrace. The entry Orchard and Mesa options are already around 93 square metres, so orientation is usually a better upgrade than raw size.",
      "Camp Sarika, five minutes by vehicle or a longer walk away, is a separate ten-pavilion experience with canvas, private pools and a stronger expedition mood. It is not simply Amangiri's better room. Split stays suit travellers who genuinely want two rhythms; otherwise choose the architecture—main resort or camp—that matches the trip and stay put."
    ]},
    { heading: "What is included, and what is not", body: [
      "Current standard inclusions cover full board for two guests per room, non-alcoholic refreshments, airport transfers from Page, a scheduled wellness class and guided group hikes. Alcohol, private guiding and major excursions can move the bill substantially. Build the desired itinerary before judging the room rate, because a quiet pool stay and a week of private adventure are financially different products.",
      "The isolation is profound and deliberately maintained. Page is the practical air gateway; Las Vegas and Phoenix involve long drives. Summer heat limits exposed activity and winter changes access, making shoulder seasons attractive but never predictable. Amangiri rewards four or five nights and an appetite for landscape. Those seeking social energy, abundant restaurant choice or spontaneous town life will find the silence expensive."
    ]}
  ],
  "beverly-hills-hotel": [
    { heading: "Room, suite or bungalow", body: [
      "The main building carries the corridors, palms and easy access to restaurants; the 23 bungalows are dispersed through gardens and offer private entrances, patios and a more residential sense of remove. Famous numbers carry famous stories, but layout should matter more than celebrity association. Some bungalows include pools or highly individual features, while others earn their premium through privacy rather than scale.",
      "Entry rooms can feel surprisingly conventional beside the iconography. Ask about balcony, view and renovation date, and consider how often the party will use the pool or Polo Lounge. A remote bungalow is seductive until every coffee requires a long garden walk; a main-house room is practical until corridor traffic interrupts the fantasy."
    ]},
    { heading: "Three restaurants, three versions of Los Angeles", body: [
      "The Polo Lounge is a power dining room disguised by green stripes and bougainvillea, strongest at breakfast and lunch when the city is conducting business in public. The Fountain Coffee Room has served counter breakfasts and pie since 1949, offering a smaller, more democratic kind of nostalgia. The Cabana Cafe puts salads, burgers and cold drinks beside the pool, where lunch can occupy most of an afternoon.",
      "None should be approached solely as a celebrity safari. The hotel works when its rituals are lived rather than observed: an early counter stool, a swim before the loungers fill, a late lunch that is not rushed toward sightseeing. Non-resident diners animate the public rooms, but the pool remains reserved for overnight guests—a meaningful privilege in the Los Angeles sun."
    ]},
    { heading: "Pink does not mean soft-edged", body: [
      "The service style is warm and protective, calibrated for guests who may value privacy above recognition. That discretion coexists with a highly visible mythology and a dressier social current than the resort landscaping suggests. The hotel is family-friendly, pet-friendly within stated limits and equipped with a spa and 24-hour gym, yet its emotional centre remains adult conversation around lunch.",
      "Parking and destination logistics add materially to the bill, while traffic makes dinner across town a strategic decision. Stay here to inhabit Beverly Hills, not to sample all of Los Angeles equally. The Pink Palace has survived because it offers continuity rather than relevance on demand. Guests who enter that rhythm usually stop asking whether a newer hotel has a larger television."
    ]}
  ],
  "fogo-island-inn": [
    { heading: "A social enterprise before it is a design object", body: [
      "Fogo Island Inn was created by Shorefast, a registered Canadian charity founded by islander Zita Cobb. Operating surpluses support community and economic programmes, while the organisation's economic-nutrition approach sets out where money from a purchase goes. That structure does not make every hospitality detail beyond criticism, but it changes the relationship between remote luxury and the place providing it.",
      "Local makers produced quilts, textiles and furniture throughout the inn; artists and residents participate in a wider network of studios and projects. The most responsible stay does not consume this story as moral decoration. Ask questions, spend beyond the inn, take community hosts seriously and remember that Fogo is home before it is an aesthetic of salt, fog and timber."
    ]},
    { heading: "Twenty-nine rooms facing weather", body: [
      "Every guest room looks toward the North Atlantic, but size and plan vary from compact rooms to multi-level suites. Wood-burning stoves, handmade furniture and enormous windows direct attention outward; televisions would lose the argument. The white interiors make winter light feel almost liquid and storms theatrical. They can also feel exposed, especially to travellers expecting the padded hush of a conventional resort.",
      "The inn stands on stilts beside Joe Batt's Arm, reached after a flight to Gander and onward road and ferry or arranged air connection. Weather is not a scenic guarantee but an operating condition. Build buffers around flights, carry proper layers and avoid a short itinerary whose emotional success depends on one clear day."
    ]},
    { heading: "Seven seasons, not one best month", body: [
      "The island describes seven seasons, from pack ice and spring to berry time, late fall and winter. Each creates a different hotel: icebergs may pass offshore, summer opens trails and boats, autumn brings berries and changing light, winter turns the hearth into infrastructure. Choose the season for the desired activity rather than treating cold or fog as a booking failure.",
      "Food interprets Newfoundland ingredients through preservation, seafood, berries and a kitchen shaped by what the island can provide. The rate generally gathers meals and many experiences into the stay, but inclusions and transfers should be checked. Fogo is not for guests who require a spa circuit, nightlife or frictionless access. It is for those willing to let weather and conversation replace the usual resort programme."
    ]}
  ],
  "explora-patagonia": [
    { heading: "Location inside Torres del Paine", body: [
      "Explora sits at Salto Chico beside Lake Pehoé, within Torres del Paine National Park rather than at a distant gateway. The position reduces transfer time to many trailheads and keeps the Paine massif in view through breakfast, weather and evening. It also means there is no town outside the door. Guests commit to the lodge's transport, guiding and meal rhythm for the duration.",
      "Rooms are deliberately calm and largely free of electronic distraction, with windows doing the decorative work. Salto Chico categories face the waterfall; Cordillera Paine rooms turn toward the massif. The view difference is substantive, not marketing punctuation. Light sleepers should ask about room position relative to public areas and the water's constant sound."
    ]},
    { heading: "The exploration model", body: [
      "Guides propose daily small-group explorations according to weather, ability and interest, spanning short walks, full-day hikes, overland routes and horseback riding. This consultation is the real check-in. Be candid about knees, pace and experience; Patagonia punishes bravado, and a 'moderate' route can become serious when wind and rain arrive sideways.",
      "Private guiding can add flexibility but is not necessary for a strong stay. Group composition matters more. The best guides explain glaciology, plants, ranching and conservation between headline viewpoints, turning a difficult weather day into more than a failed photograph. Leave one easier day in the plan; fatigue accumulates and the landscape deserves attention outside a summit objective."
    ]},
    { heading: "All-inclusive, with caveats", body: [
      "Accommodation, meals, transfers on set schedules and most guided explorations are commonly bundled, which makes the high price more intelligible than a room-only comparison suggests. Premium wine, private services and certain logistics may sit outside a package. Confirm the exact airport—Punta Arenas or Puerto Natales—pickup window before purchasing flights, because a missed shared transfer can create an expensive private solution.",
      "The spa and heated pool offer recovery rather than resort spectacle. Food must satisfy hikers repeatedly and tends toward generous, well-executed comfort. Explora is not ideal for travellers who want restaurant choice, an unstructured lie-in or independent driving every day. It excels when activity, guiding and logistics are allowed to function as one coherent product."
    ]}
  ],
  "one-and-only-cape-town": [
    { heading: "Waterfront convenience, resort scale", body: [
      "The V&A Waterfront is Cape Town's most frictionless visitor base: restaurants, shops, the Zeitz MOCAA precinct and Robben Island ferries are close, while secure public spaces remain lively after dark. It is also a managed district rather than a neighbourhood that reveals the city's full complexity. One&Only uses canals, gardens and a large pool to soften that commercial setting, creating a resort inside an urban itinerary.",
      "The Marina Rise holds the grand lobby and Table Mountain-facing rooms; low Island accommodation sits around waterways closer to the spa and pool. The latter feels calmer and more residential, while the former delivers the hotel's defining mountain composition. Families should value proximity to facilities; first-time visitors may find the big view worth the busier building."
    ]},
    { heading: "Rooms made for a longer city stay", body: [
      "The hotel claims some of Cape Town's largest rooms and suites, and the generosity is useful rather than merely impressive. Dressing areas, proper bathrooms and balconies make four or five nights comfortable, especially when weather rearranges plans. Mountain views depend on cloud as much as category; a clear morning should never be postponed because Table Mountain can disappear by lunch.",
      "The resort was comprehensively refreshed in the early 2020s, bringing African art and warmer materials into spaces once defined by generic international luxury. It remains polished and large-scale rather than intimate. Travellers looking for the city's sharper design culture should visit galleries and independent restaurants, using the room as a highly capable retreat."
    ]},
    { heading: "ROOI, Isola and the island spa", body: [
      "ROOI centres South African ingredients around fire, with meat, game and vegetables carrying the menu's sense of place. Isola handles poolside Mediterranean-leaning lunches; Vista Bar frames Table Mountain for tea and cocktails. The Wine Loft can deepen an evening, but Cape Town's restaurant scene is too good for full-board habits. Reserve outside tables as carefully as those inside the hotel.",
      "The spa occupies its own island and supplies an unusually complete pause between mountain, winelands and city days. This is One&Only's strongest argument: not that it replaces Cape Town, but that it makes an ambitious Cape Town itinerary recoverable. Guests wanting nightlife at the door or a small-house atmosphere should choose differently; families and first-time visitors will appreciate the operational ease."
    ]}
  ],
  "giraffe-manor-nairobi": [
    { heading: "The breakfast photograph, explained", body: [
      "Giraffes visit the manor at breakfast because the property adjoins the forested sanctuary where a resident herd roams; the animals are not furniture and the encounter is managed around their behaviour. Tables are assigned by staff for safety, circulation and group size. Guests cannot reserve the most photogenic window, though everyone is given an opportunity to feed the giraffes. Weather and animals decide the precise choreography.",
      "That clarification matters in a hotel sold through a single viral image. Long necks entering a sunroom window are astonishing, but breakfast is brief and closely supervised. The better memory may be watching a giraffe cross the lawn without performing for anyone. Listen to handlers, keep food to approved pellets and allow the animal to leave the frame."
    ]},
    { heading: "Twelve rooms in two manors", body: [
      "The original 1932 manor and the newer Garden Manor contain 12 individually planned rooms in total, including family suites. Main Manor guests breakfast in its sunroom; Garden Manor guests use their own dining room. Certain rooms have balconies or direct giraffe-facing windows, but architecture and access differ enough that floor plans should be read before booking.",
      "The house sits on 12 private acres within a much larger indigenous forest in Langata, away from central Nairobi's business districts. It works beautifully as the first or final night of a safari circuit and poorly as a daily base for meetings across town. Traffic and airport timing require generous buffers; The Retreat next door can provide day rooms and wellness facilities for eligible itineraries."
    ]},
    { heading: "Conservation, access and scarcity", body: [
      "Demand is intense and overnight guests receive priority; external breakfasts and teas are not generally offered. Some Garden Manor inventory is more widely bookable while other rooms may be prioritised for guests combining Safari Collection properties, with late availability sometimes released. This is not a place to organise on arrival. Use the operator's live calendar and be wary of third parties promising an animal encounter without a confirmed room.",
      "The experience should be connected to the conservation work around Rothschild's giraffe rather than consumed as novelty. Ask staff about the breeding and reintroduction story, visit the adjacent Giraffe Centre if appropriate and give Nairobi more than a transfer window. The manor is enchanting, but its value depends on treating the giraffes as the reason for protection, not props supplied with breakfast."
    ]}
  ],
  "khyber-himalayan-gulmarg": [
    { heading: "At 8,825 feet, logistics are part of luxury", body: [
      "The Khyber sits above Gulmarg close to the gondola, but Kashmir travel cannot be planned like an ordinary resort weekend. Weather, road conditions, security guidance and gondola operations can alter a day quickly. Arrange airport transfers through a reliable operator, carry identification and build time around the Srinagar drive. In winter, appropriate vehicles and chains are necessities, not upgrades.",
      "Altitude is noticeable on arrival, particularly after a long journey. Begin slowly, hydrate and let the first afternoon belong to the view. The hotel has in-house medical assistance, but travellers with relevant health concerns should seek professional advice before the trip. The mountain is beautiful precisely because it does not operate on a guest's timetable."
    ]},
    { heading: "Which side of the hotel", body: [
      "The 85-key inventory ranges from 386-square-foot Premier Rooms to larger balcony categories and one- or two-bedroom cottages. Gulmarg View rooms look over gardens and meadows; Himalayan View rooms turn toward the mountains and can justify their premium when weather opens. A balcony is more valuable in summer and shoulder season than in deep snow, when a warm window seat may be the practical luxury.",
      "Interiors use timber, Kashmiri craft references and deep colours to create an alpine rather than palace mood. The public rooms become busy when lifts close and weather drives everyone indoors. Couples seeking quiet should request distance from family circulation; groups should secure connecting arrangements early because ski weeks concentrate demand."
    ]},
    { heading: "After the gondola", body: [
      "The hotel is not ski-in/ski-out in the European sense, though proximity to the Gulmarg Gondola is a major advantage. Equipment, lift tickets, guides and avalanche conditions need separate attention. Off-piste terrain is serious and should be approached only with qualified local expertise. In summer, walks, meadow rides and the outdoor Niku pop-up replace snow sports with a gentler mountain rhythm.",
      "Brava supplies Italian comfort, while Nouf is positioned for more intimate dining; seasonal outlets vary. The L'Occitane spa and heated indoor pool are crucial after cold days. The Khyber's strength is giving Gulmarg a credible luxury base, not insulating guests from the realities of the Himalaya. Those realities should shape every booking decision."
    ]}
  ],
  "jai-mahal-palace-jaipur": [
    { heading: "Eighteen acres in the middle of Jaipur", body: [
      "Jai Mahal began as an eighteenth-century residence and now sits within 18 acres of Mughal-style gardens in Civil Lines. That position is less immersive than the walled city and more practical for travellers who want lawns, parking and a pool between excursions. Amber Fort, City Palace and Johri Bazaar still require driving; Jaipur traffic makes their apparent proximity unreliable at peak hours.",
      "The palace's low, long facade creates a garden hotel rather than a vertical urban one. Evening entertainment and events can bring energy to the lawns, while wedding seasons introduce sound and restricted areas. Ask about scheduled functions before choosing a garden-facing room. A heritage setting is also a working celebration venue."
    ]},
    { heading: "One hundred rooms, not one plan", body: [
      "The official inventory lists 94 rooms and six suites, with 22 pool-facing and 54 garden-facing rooms. Interiors vary between more historic decorative schemes and contemporary Taj polish. Outlook and distance from public spaces are more consequential than a romantic category name, especially when an event occupies the lawns.",
      "Families value the space, kids' activities and outdoor pool; couples may prefer one of the suites or a quieter wing. Travellers comparing Jai Mahal with Rambagh should understand the distinction. Rambagh supplies greater palace ceremony and a higher tariff; Jai Mahal is usually more relaxed, greener and easier to inhabit without turning every hour into an occasion."
    ]},
    { heading: "Where to eat, and when to leave", body: [
      "Cinnamon serves Rajasthani and Mughal dishes in the formal register; Giardino handles Italian food; Marble Arch is the all-day room and Marigold the bar. The breadth supports a multi-night stay, though Jaipur's restaurant scene deserves at least one evening beyond the gates. Use the hotel for a restorative lunch after sightseeing and save local appetite for a specialist kitchen in town.",
      "The J Wellness Circle and gardens give the property a resort-like afternoon, making it well suited to first-time visitors who need decompression. It is less convincing for travellers seeking cutting-edge design or immediate bazaar life. Book for usable space, established service and a softer landing in Jaipur—not because every decorative detail is museum-grade."
    ]}
  ],
  "pashan-garh-taj-safari": [
    { heading: "A stone lodge outside Panna", body: [
      "Pashan Garh lies in the dry forests near Panna National Park, its 12 stone cottages inspired by local houses and set apart along winding paths. The landscape is more rugged than manicured, with teak, scrub and large boulders shaping the mood. Nights require an escort and sensible shoes; wildlife does not recognise the distinction between reserve and lodge grounds.",
      "The cottages use slate, stone, leather and regional textiles rather than a generic tented-safari vocabulary. Each has a veranda and enough distance for privacy, though forest outlooks vary with vegetation and season. There is no point demanding a view of animals from bed. The room's job is to hold the heat outside, the quiet inside and the body comfortably between drives."
    ]},
    { heading: "Panna is not a guaranteed tiger photograph", body: [
      "The park's tiger recovery story is significant, but sightings remain chance encounters shaped by range, weather and animal movement. Guides and naturalists should be judged on how they interpret the whole ecosystem—vultures, crocodiles, deer, tracks and forest—rather than on whether a single cat appears. A three- or four-night stay improves the odds and reduces the temptation to rush every drive.",
      "Panna's broader region includes the Ken River and the temples of Khajuraho, allowing a trip to combine wildlife with architecture. Transfers and park permits need advance coordination. Domestic flight schedules change, road journeys take longer than maps suggest and park zones may affect drive time, so the lodge should be involved before the rest of the itinerary hardens."
    ]},
    { heading: "Meals, inclusions and who should come", body: [
      "Dining often moves between the main lodge, deck, bush and private settings, using Indian comfort food and regional flavours to sustain early starts. Exact meal, drive and transfer inclusions vary by package and should be read closely; safari pricing becomes misleading when permits and vehicles are separated from the room.",
      "Pashan Garh suits travellers who want a small lodge, attentive naturalists and a landscape less crowded by international safari mythology. It is not for guests who need a large spa, extensive restaurant choice or constant connectivity. Bring patience and binoculars. The most rewarding Panna day may be the one in which a tiger never appears."
    ]}
  ],
  "oberoi-new-delhi": [
    { heading: "The capital, edited through glass", body: [
      "The Oberoi stands on Dr Zakir Hussain Marg between the Delhi Golf Club and Humayun's Tomb, a location that gives unusually open views in a city where hotel windows often meet roads or other buildings. Golf-course rooms receive green calm; monument-facing rooms place the tomb and Nizamuddin skyline in the distance. Neither view makes the air or traffic disappear, but both give the room a horizon.",
      "The hotel was rebuilt behind its familiar shell and reopened in 2018 with 220 rooms and suites, fewer and larger than before. Interiors are precise, pale and contemporary, with technology kept intuitive. It now feels like a purpose-built modern capital hotel rather than a nostalgic grande dame, which will please travellers who value function and disappoint those seeking the decorative density of an Indian palace."
    ]},
    { heading: "Clean air is an operating system", body: [
      "Delhi's seasonal pollution makes filtration more than marketing. The Oberoi installed comprehensive indoor air-cleaning systems and displays air-quality information, a meaningful advantage during difficult months. No hotel can control exposure in cars or streets, and sensitive travellers should still follow health guidance, but the ability to return to monitored indoor air changes the practical comfort of a winter stay.",
      "The rooftop and pool areas remain exposed to weather and air conditions; plans should flex accordingly. Summer heat, monsoon rain and winter fog each alter the hotel's best spaces. A supposedly inferior season may still work well for museums and meetings if expectations are set around climate rather than postcard assumptions."
    ]},
    { heading: "Four dining moods", body: [
      "360° is the polished all-day room; Omya interprets Indian food in a contemporary register; Baoshuan, associated with Andrew Wong, looks toward China; Cirrus9 puts cocktails on the roof. The breadth makes the hotel unusually self-sufficient for business stays, but Delhi's food culture requires leaving. One meal in Old Delhi or at an independent modern Indian restaurant supplies context no luxury dining room can reproduce.",
      "Service is the real reason many guests return: formal enough for state-capital expectations, quick enough for a tight schedule and generally alert to individual habits. The hotel suits first-time visitors, business travellers and anyone prioritising sleep, air and logistics. It is less appropriate for guests who want to walk outside into markets and cafés."
    ]}
  ],
  "w-goa": [
    { heading: "Vagator, not generic Goa", body: [
      "W Goa occupies the red cliffs above Vagator in North Goa, with Chapora Fort and the Arabian Sea shaping the view. This is a social, music-led part of the state rather than the quiet south. Beaches, restaurants and nightlife are close by car or scooter, but the resort's slope and gates mean it does not function as a walk-out village hotel. Weekend traffic should be allowed to dictate dinner timing.",
      "The architecture spreads across grounds rather than rising as a single block. Rooms, chalets and villas vary in privacy, level and distance from the sea; Portuguese-style balconies and garden positions can be as useful as a nominal ocean category. Guests with limited mobility should request a convenient location and confirm internal transport."
    ]},
    { heading: "Three pools and a changing social map", body: [
      "WET is the central resort pool, Rockpool occupies the cliff edge and the vitality pool sits within the subterranean AWAY Spa. Rockpool's sunsets over Vagator made it the signature, but the hotel's own current listing has marked it temporarily closed at points in 2026. Confirm access for the exact stay instead of booking an old photograph.",
      "The spa draws on Roman-bath imagery through corridors, eight treatment rooms, steam, sauna and vitality water. It provides an effective counterpoint to W's amplified public areas. Families can find space, yet event weekends and DJ programming change the atmosphere quickly. Ask what is scheduled; at this brand, the calendar is part of the room product."
    ]},
    { heading: "Goa on the menu—and beyond it", body: [
      "Spice Traders currently focuses on modern Chinese cooking, The Kitchen Table handles all-day meals and WOOBAR moves from lounge to nightlife; Sylvia extends the cocktail offer above Spice Traders. Concepts evolve more quickly here than at a heritage hotel, another reason to use current pages rather than inherited descriptions. Local ingredients appear, but this is an international resort palate, not a survey of Goan food.",
      "Leave for fish thali, poi, cafreal and the state's smaller kitchens. W Goa is most convincing when used as an energetic base with a serious spa, not as a sealed account of the destination. It suits groups and couples who want sunsets and social life. Travellers seeking quiet, immediate sand and regional intimacy should look farther south or to a smaller house."
    ]}
  ],
  "w-koh-samui": [
    { heading: "Seventy-four villas, seventy-four pools", body: [
      "Every villa has a private pool, which removes the usual resort hierarchy between those who can retreat and those who cannot. The differences instead lie in garden privacy, ocean elevation and true beachfront access. Entry Escape villas sit in tropical planting; Ocean View categories climb the slope; the largest two-bedroom residence expands to a scale intended for families and groups.",
      "A sea view in Samui does not automatically mean easy swimming. Tide, reef and seasonal water conditions change along the northern coast, while the property spans headland between Maenam and Bo Phut outlooks. Ask which categories have steps to sand, how private the pool is and what the beach is doing in the travel month."
    ]},
    { heading: "The W mood in island form", body: [
      "WOOBAR's sunken seating and broad water view form the social centre, with music and fire shows carrying the space after dark. The Kitchen Table provides breakfast and broad comfort; Namu interprets Japanese food; SIP & Beach Grill uses the sand and sunset. Guests seeking a silent wellness retreat can find quiet inside a villa but will be resisting, rather than joining, the hotel's public personality.",
      "AWAY Spa has seven treatment rooms and its own pool, while FIT, water activities and the main WET deck supply activity. Service follows the brand's informal Whatever/Whenever language, though island logistics still require advance notice. A last-minute boat or difficult dinner reservation cannot always be solved by branding."
    ]},
    { heading: "When the private pool is worth it", body: [
      "The villa format works especially well for couples who want social evenings and private days, and for families who need naps or early meals without abandoning the water. It can also reduce engagement with Samui. Fisherman's Village, local restaurants and quieter stretches of the north coast deserve time beyond the gates.",
      "Rates should be compared with meal and transfer costs, not with ordinary rooms elsewhere on the island. Marriott Bonvoy benefits and breakfast inclusions vary by booking channel and status. W Koh Samui offers a distinctive, extroverted resort with genuine privacy at bedroom level; it is not the answer for minimalists or travellers who equate barefoot with unstyled."
    ]}
  ],
  "stay-wellbeing-phuket": [
    { heading: "A training resort, not a beach resort", body: [
      "STAY sits in Rawai rather than on one of Phuket's classic swimming beaches. The location makes sense for long stays, training and trips around the south of the island; it makes less sense for travellers who expect to step from breakfast onto sand. Nai Harn and Rawai's seafront require transport, and island traffic can turn a simple dinner into a plan.",
      "What replaces the beach is serious fitness infrastructure. STAYFIT occupies three floors with strength and cardio equipment, studios and group classes spanning yoga, cycling, Muay Thai, HIIT and bootcamp. The facility also serves members beyond the hotel, so peak hours can feel like a successful club rather than a private resort gym."
    ]},
    { heading: "Rooms designed for routine", body: [
      "Accommodation ranges from 35-square-metre Junior Suites to multi-bedroom pool villas, generally with large balconies and a clean, apartment-like aesthetic. Many units add washing and drying facilities, useful for training clothes and long stays. Pool-access categories are convenient but sacrifice some privacy as other guests move past the terrace.",
      "The larger villas offer kitchens, living areas and multiple levels, making them practical for groups following different schedules. They are less compelling for a two-night beach break. Choose based on how the day will actually work—laundry, meals, classes and recovery—rather than on the most impressive square-metre figure."
    ]},
    { heading: "Recovery is treated as seriously as exercise", body: [
      "The spa operation includes wet onsen areas, float therapy, ice bathing and numerous treatment rooms, creating an unusually complete recovery circuit. The main pool landscape and healthy dining support guests who want structure without entering a clinical retreat. Food still needs pleasure; a wellness hotel fails when every dinner tastes like compliance.",
      "STAY is best for solo travellers, athletes, remote workers and groups who will use the gym daily. It is not a substitute for Phuket's finest coastline or Thai design heritage. The resort's honesty lies in its priorities: train, eat, sleep, recover. Guests who share them may stay weeks; those who do not may feel they booked membership with a bedroom attached."
    ]}
  ],
  "rambagh-palace-jaipur": [
    { heading: "The palace as lived history", body: [
      "Rambagh developed from a garden residence into the home of Jaipur's maharajas before becoming a hotel in the mid-twentieth century. The sequence of courtyards, verandas, marble and lawns was made for ceremonial life, not efficient check-in. That history gives the building authority no newly constructed palace can fully reproduce—and creates long walks, irregular plans and rooms that differ even within a category.",
      "The location on Bhawani Singh Road sits outside the walled city with grounds large enough to mute traffic. City Palace, bazaars and Amber Fort still require driving. Guests should not confuse a palace view of Jaipur with immersion in its daily streets; the hotel's scale is a retreat from the city, best balanced by purposeful excursions."
    ]},
    { heading: "Choose the room for architecture", body: [
      "Some rooms occupy historic palace sections with high ceilings, arches and individual details; others reflect later hotel layers. Palace suites add named histories and formal salons, but can feel excessive for a couple who spends most days outside. Ask about stairs, terrace, view and distance from restaurants. At Rambagh, a smaller room in the right wing may carry more atmosphere than a larger, generic plan.",
      "The interiors favour Indian decorative richness, with textiles, carved furniture, chandeliers and marble. This is not where to demand contemporary minimalism. The relevant question is maintenance: old buildings require constant attention, and at this tariff every fitting, fabric and air-conditioning vent should support rather than excuse the romance."
    ]},
    { heading: "Dining and the theatre of evening", body: [
      "Suvarna Mahal stages Indian fine dining in the former palace ballroom beneath chandeliers and frescoes; the Steam restaurant uses a restored train carriage and platform; verandas and lawns host tea and drinks. These are experience-led venues, sometimes more memorable for setting than culinary surprise. Reserve the formal dinner once, then seek Jaipur's contemporary and regional kitchens elsewhere.",
      "Peacocks, polo references and staff in ceremonial dress can make the hotel feel like a romantic construction of Rajasthan. The best service prevents that theatre from becoming stiff, bringing warmth and humour back into the building. Rambagh is for milestones and travellers who want a palace to behave like one. Those prioritising privacy, small scale or old-city immediacy should choose another Jaipur story."
    ]}
  ],
  "umaid-bhawan-jodhpur": [
    { heading: "A palace still divided between hotel and home", body: [
      "Umaid Bhawan was completed in the 1940s as one of the last great palaces built in India, its sandstone mass combining classical symmetry, Art Deco geometry and Rajasthani craft. The royal family still occupies part of the building; Taj operates 71 rooms and suites in another. That living continuity distinguishes it from a converted monument and also keeps portions of the palace private.",
      "The hilltop position gives the dome and lawns tremendous authority but removes guests from Jodhpur's blue lanes. Mehrangarh, the old city and stepwell require a car. Return journeys can be slow around events, and the palace's own museum attracts daytime visitors. The reward is space—26 acres of gardens, peacocks and a skyline seen from above rather than within."
    ]},
    { heading: "Art Deco behind sandstone", body: [
      "The most interesting rooms resist the expected palace vocabulary. Palace Rooms and Historical Suites combine vintage furniture with Art Deco lines; Royal and Grand Royal Suites increase sitting space and ceremony. The Maharaja and Maharani Suites preserve dramatically different personal narratives, one with an in-room spa and steam room, the other with softer colours, a kitchenette and fort views.",
      "Do not pay for biography unless the layout suits the stay. Some historic suites feel formal and compartmentalised, while a simpler room may have a more persuasive lawn outlook. Ask about stairs, distance and view. The building's scale means that a beautiful room in the wrong location can make every breakfast a procession."
    ]},
    { heading: "How to inhabit the spectacle", body: [
      "Two restaurants, a bar, indoor and outdoor pools and the J Wellness Circle make the palace self-contained. One formal dinner and an evening drink beneath the dome belong in the experience; the remaining appetite should encounter Jodhpuri cooking beyond the gates. A heritage walk adds context the architecture cannot provide by itself.",
      "Weddings and events can transform the lawns, so confirm dates before booking a quiet retreat. Service tends toward ceremony, yet the stay is strongest when staff let the building feel like a home rather than a stage set. Umaid Bhawan is for travellers who want scale, lineage and an unapologetic sense of occasion. Those seeking intimacy should choose a haveli closer to the fort."
    ]}
  ],
  "raffles-singapore": [
    { heading: "All suites, all verandas", body: [
      "Raffles emerged from its 2017–2019 restoration with 115 suites arranged around white arcades, courtyards and gardens. Fourteen-foot ceilings, teak floors and separate parlours preserve the horizontal rhythm of the old hotel, while concealed technology and air-conditioning keep history from becoming hardship. Courtyard, Palm Court and Personality categories differ in outlook and narrative more than basic comfort.",
      "The building's low rise is a luxury in modern Singapore, but it creates walking distance and exposure between rooms and facilities. Ground-floor suites place the veranda close to public circulation; upper suites gain separation but add stairs and lifts. Ask how much privacy matters relative to immediate access to the lawn, pool and lobby."
    ]},
    { heading: "The Singapore Sling is only the beginning", body: [
      "The Long Bar performs the peanut-shell ritual and the origin story of the Singapore Sling for a continuous stream of visitors. Have the drink if curiosity demands it, then move on. Writers Bar is calmer and more adult; Raffles Courtyard brings tropical air to drinks and Southeast Asian dishes; the Grand Lobby carries afternoon tea with full ceremony.",
      "Tiffin Room has served North Indian cooking in various forms since the nineteenth century, while Butcher's Block uses live-fire techniques in a contemporary setting. The hotel's dining history is real, but Singapore's hawker centres and independent restaurants are indispensable. Raffles should frame that appetite, never contain it."
    ]},
    { heading: "A national monument with hotel duties", body: [
      "The public comes to photograph the porte-cochère, shop in the arcade and drink at the bars. Resident-only areas, including the pool, restore privacy but cannot turn the whole landmark into a private club. Butler service helps negotiate the building and the city; its best use is securing time and solving details, not staging unnecessary ceremony.",
      "The location at 1 Beach Road is exceptionally practical for the civic district, museums and Marina Bay. New luxury towers offer higher views and flashier pools. Raffles offers shade, proportion and the sensation of sleeping within Singapore's own historical imagination. Book at least two nights and leave the Sling queue to day visitors after the first round."
    ]}
  ],
  "amankila-bali": [
    { heading: "East Bali changes the pace", body: [
      "Amankila occupies a hillside above the Lombok Strait near Manggis, far from the restaurant density and traffic of Seminyak and Canggu. The drive from the airport is long and variable, but current stay inclusions list round-trip airport transfers as well as a local shuttle around Manggis and Candidasa. Once there, East Bali's water palaces, villages and Mount Agung give excursions a coherent geography.",
      "The resort descends through frangipani-lined paths, pavilions and its three-tier pool before reaching a separate Beach Club on black sand. This vertical plan produces privacy and sea views; it also creates steps. Guests with mobility concerns should discuss pavilion location and buggy use before arrival rather than assuming a clifftop resort is effortless."
    ]},
    { heading: "Pavilions before private pools", body: [
      "Stilted pavilions open onto deep terraces and use timber, thatch and pale stone to frame the coast. Garden, Ocean and Kilasari positions offer different degrees of water view and separation; pool suites add private water without changing the essential architecture. The classic pavilion remains compelling enough that an upgrade should buy a precise view, not status.",
      "The two-bedroom Amankila Villa expands to 660 square metres with a private pool, butler and extraordinary space for families. For couples, greater distance can work against the intimacy of the resort. Ask how far the pavilion sits from the main pool and beach route, and remember that the shared three-tier pool is the design gesture people cross continents to see."
    ]},
    { heading: "A dining programme rooted in the east", body: [
      "Sandikala serves Indonesian and international food above the pool; Arva brings southern Italian cooking; the Beach Club handles lighter meals beside the coconut grove. The kitchen draws from an organic garden, local fishing and East Balinese traditions, with megibung sharing dinners, rijsttafel, sunrise cruises and meals at Ujung Water Palace extending the table beyond the restaurant.",
      "Private experiences can multiply quickly and deserve selection. Choose one that deepens location—perhaps the Karangasem dinner or a jukung at sunrise—rather than purchasing romance by the hour. Amankila is best for travellers content with quiet, stairs and a long transfer. Those wanting nightlife or a swimmable white-sand beach immediately outside every room should book a different Bali."
    ]}
  ],
  "four-seasons-bali-sayan": [
    { heading: "Arrival through the rice bowl", body: [
      "The resort's famous arrival crosses a bridge above the Ayung valley and descends onto a circular lotus roof before the river and forest reveal themselves. It is not simply a photogenic device: architect John Heah reversed the usual lobby sequence, making guests move down into the landscape. Villas then disappear along paths below, while suites occupy the main structure closer to restaurants.",
      "Sayan lies outside central Ubud, close enough for temples, galleries and meals but far enough that traffic must be planned. A short distance can become a long transfer in the afternoon. The resort is strongest when town visits are concentrated and whole half-days remain beside the river, rather than when every meal is booked on the other side of Ubud."
    ]},
    { heading: "Suite or pool villa", body: [
      "Suites place couples near the architectural centre and can offer stronger valley views for less money. One-bedroom villas add walls, gardens and private plunge pools; family and two-bedroom villas provide serious shared space. Dense tropical planting creates privacy but can reduce panorama, so a villa is not automatically the view upgrade it appears to be.",
      "Interiors mix teak, hand-loomed textiles, terrazzo bathrooms and contemporary comfort. Humidity, insects and the river's sound are part of the environment, not signs that nature has breached a sealed resort. Guests who need absolute acoustic or climatic control should request a room closer to the main building."
    ]},
    { heading: "River rituals and responsible pacing", body: [
      "Ayung Terrace interprets Indonesian dishes above the valley; Riverside brings Mediterranean flavours to the water; Jati Bar works for tea and a late drink. Cooking, yoga, rice-field walks and spa rituals can fill a programme, while 24-hour in-villa dining makes staying put easy. Resist converting Balinese culture into an appointment every hour.",
      "The river can be loud and paths steep, especially after rain. Families should ask about pool safety and buggy response; couples should consider distance from public areas. Four Seasons makes Sayan unusually easy without stripping away its humidity and verticality. Book for architecture, service and access to Ubud's inland life—not for a beach holiday transported into the hills."
    ]}
  ],
  "the-datai-langkawi": [
    { heading: "Rainforest first, beach second", body: [
      "Kerry Hill's original plan placed the resort within mature lowland rainforest rather than clearing it for a sea view. The main building sits high in the canopy; rainforest villas descend among streams and buttress roots; beach villas finally meet Datai Bay. That sequence is the hotel's identity. Wildlife—dusky langurs, macaques, hornbills, colugos and frogs—moves through it on its own terms.",
      "The 2017–2018 restoration retained Hill's architectural language under Didier Lefort while refreshing all 121 rooms, suites and villas and adding the Nature Centre. The result remains dark, timbered and inward-looking in places. Guests seeking uninterrupted blue from every bed should choose the Beach Collection; those choosing Datai for its forest should not complain when trees win the view."
    ]},
    { heading: "Three collections, three holidays", body: [
      "Canopy rooms and suites sit near the lobby and main pool, convenient for restaurants and strong over the treetops. Rainforest villas offer greater immersion and privacy but require buggies or walks to the beach. Beach villas add pools, butlers and immediate sand at a much higher price. The vast five-bedroom Datai Estate is a separate proposition for groups, with its own staff and two connecting pools.",
      "Families should balance water access against independence; couples may prefer forest seclusion. Mobility needs must be raised early because the hillside is intrinsic to the plan. No category solves every distance. The useful question is where the party wants to wake and spend late afternoon, not which room sits highest on the rate sheet."
    ]},
    { heading: "Naturalists and night dinners", body: [
      "The bamboo Nature Centre houses resident naturalists and marine biologists and leads into walks across several habitats. These are not filler activities. A good guide turns a green wall into competition for light, food and territory, making the resort's design choices intelligible. The Datai Pledge adds conservation and community programmes whose claims guests can examine directly.",
      "The Gulai House serves Malaysian food in a forest kampung setting; The Pavilion rises on 30-metre stilts for Thai dinners; beach and dining rooms cover the day's simpler appetites. Eat regional dishes first. The Datai succeeds because food, architecture and natural history share the same landscape. It is less suited to nightlife seekers or travellers wanting to explore Langkawi independently every day."
    ]}
  ],
  "nihi-sumba": [
    { heading: "The journey is part of the filtering", body: [
      "NIHI sits on Sumba's remote southwest coast, reached through Bali and a domestic flight followed by a long road transfer. Connections should be buffered; weather and airline schedules can unpick a tightly chained itinerary. The distance protects the sense of arrival and makes very short stays irrational. Five nights is a beginning, seven allows the island to move beyond resort scenery.",
      "The villas spread along slopes above Nihiwatu Beach, each with a different arrangement of pools, pavilions and bedrooms. The best category depends on stairs, privacy and proximity to the main hub, not merely ocean view. Families should scrutinise railings and pool layouts; surfers should discuss access to the wave rather than assume a room rate includes an uncrowded session."
    ]},
    { heading: "Horses, surf and Spa Safari", body: [
      "The Sandalwood horses are central to NIHI's imagery and to Sumbanese culture. Riding programmes range from beach outings to deeper equine retreats, with experience requirements and welfare protocols worth discussing. The famous surf break is controlled for limited guest use and requires ability; the ocean can be powerful, and this is not a generic learn-to-surf beach.",
      "Spa Safari sends guests along the coast by hike, vehicle or horse to Nihioka for several hours of treatments above the sea; an overnight villa can extend the escape without Wi-Fi. It is genuinely distinctive and also expensive, with transport and specific therapies carrying supplements. Choose it as a full day, not an item squeezed between other activities."
    ]},
    { heading: "Luxury within a living island", body: [
      "NIHI's relationship with Sumba cannot be reduced to village visits. The Sumba Foundation supports health, water, education and livelihoods, and guests should learn how activities are designed with communities rather than assuming proximity equals benefit. Photography requires permission; poverty is not cultural texture for a resort story.",
      "Food, horses, wild beach and unusually individual villas create an emotional, less polished style than a global-brand island resort. Service can move at the pace of remoteness, and humid weather tests maintenance. That texture is part of the appeal for adventurous travellers and a warning for those who want every edge smoothed. NIHI is not perfect; it is difficult to confuse with anywhere else."
    ]}
  ],
  "the-savoy-london": [
    { heading: "Two architectural languages", body: [
      "The Savoy's rooms divide broadly between Edwardian theatricality and Art Deco geometry, a distinction more useful than a ladder of generic luxury adjectives. River-facing suites add the Thames, London Eye and bridges; courtyard and city rooms can be quieter but lose the view that makes the Strand address emotionally legible. Ask which style, outlook and renovation period apply to the exact room.",
      "The hotel sits between theatreland and the river, with Covent Garden, the National Gallery and South Bank within walking range. Cars approach via Savoy Court, famously driving on the right. That arrival is delightful and the surrounding Strand traffic is not. Rail and walking often beat taxis when the evening curtain time matters."
    ]},
    { heading: "A drinking hotel with serious restaurants", body: [
      "The American Bar is London's longest-surviving cocktail bar and still treats a menu like cultural history, with live music and reservations increasingly important. The black-and-gold Beaufort Bar is darker and more nocturnal. One drink in each reveals more of the hotel than an attempt to rank them; the real pleasure is watching bartenders adapt classics to the guest rather than the other way around.",
      "Dining now includes Gallery for all-day meals and tea, Savoy Grill, the seafood-focused River Restaurant and intimate Restaurant 1890, with Simpson's returning in 2026 under a new chapter. This abundance can turn the lobby into a destination crowd. Residents should reserve key tables before arrival and keep one night free for Soho or Covent Garden."
    ]},
    { heading: "The grande dame as working machine", body: [
      "A naturally lit pool, sauna, steam room, treatment rooms and 24-hour gym sit below the historical spectacle and become invaluable after rain or a long flight. Service must coordinate theatre diners, bar visitors, events and hotel guests without allowing the latter to feel peripheral. At its best, the operation converts enormous complexity into charm; at peak moments, the public rooms can feel more station than salon.",
      "The Savoy suits travellers who want London history with wit rather than hushed Mayfair formality. Entry rooms can seem costly for their size and river categories escalate quickly. Pay for the view if mornings in the room matter; otherwise spend on a memorable bar and use the location. The building is most alive when treated as part hotel, part stage."
    ]}
  ],
  "gritti-palace-venice": [
    { heading: "A Grand Canal position that cannot be replicated", body: [
      "The Gritti occupies a fifteenth-century palazzo at a bend of the Grand Canal opposite Santa Maria della Salute. Arriving by water is not optional theatre but the most coherent approach: the facade, traffic and church dome assemble before the boat reaches the private landing. From the door, Piazza San Marco and the Accademia are close enough to walk, while quieter Dorsoduro lies across the bridge.",
      "That centrality brings boat noise and constant motion. Canal-facing rooms turn it into spectacle; inward rooms provide more sleep and less sense of place. Venice floods, stairs and historic fabric create accessibility questions no generic five-star label answers. Discuss landing access, lift routes and room thresholds before booking."
    ]},
    { heading: "Rooms dense with Venetian craft", body: [
      "Silks, Murano glass, terrazzo, antiques and patterned walls give rooms a layered, unapologetically Venetian character. Suites named for Hemingway, Somerset Maugham and Peggy Guggenheim carry stories, but outlook and terrace usually matter more than literary association. The hotel has fewer than 100 rooms, yet palazzo geometry ensures meaningful variation in plan and light.",
      "Bathrooms and technology were modernised in the major restoration without stripping away the decorative density. Minimalists may find the visual volume exhausting. Others will value sleeping in a room that could belong only to Venice. Ask whether the bed faces water, a campo or an interior court; each produces a different city."
    ]},
    { heading: "Breakfast on the canal, dinner with restraint", body: [
      "Club del Doge handles breakfast, lunch and formal dinner, while the seasonal Gritti Terrace places lunch directly over the canal. Bar Longhi and its Riva Lounge make the water part of cocktails; the Gritti Epicurean School adds classes and private tastings grounded in lagoon produce. Current chef Alberto Fol draws from the wider Veneto as well as the sea.",
      "The terrace is expensive and intensely coveted, so reserve once and avoid treating every meal as a view purchase. Venice's bacari, islands and small dining rooms deserve the rest of the appetite. The Gritti is for travellers who want to be inside the city's ornament and movement. Those wanting gardens, a pool or distance from crowds should look across the lagoon."
    ]}
  ],
  "four-seasons-george-v-paris": [
    { heading: "The Golden Triangle, at full volume", body: [
      "The George V opened in 1928 just off the Champs-Élysées and now operates as a 243-room palace of floral installations, marble and highly visible service. The Golden Triangle is convenient for couture and major avenues, less suited to travellers who want a neighbourhood bakery to define the morning. Metro and cars place the rest of Paris within reach, but the immediate world is polished, international and expensive.",
      "Jeff Leatham's flowers transform the public rooms seasonally and attract non-resident visitors. They are not a substitute for architecture, yet they give a large lobby an evolving pulse. Quiet begins beyond reception. Request a room away from lifts and event circulation if the stay is more retreat than social call."
    ]},
    { heading: "Space before Eiffel Tower", body: [
      "Entry rooms are generous by central Paris standards, with Premier Rooms running roughly 50 to 60 square metres. Suites add terraces and, in select categories, Eiffel Tower views. The landmark can be a narrow, angled glimpse rather than a cinema screen, so ask for the precise orientation and photograph. A larger room without the view may deliver better daily comfort for less.",
      "Pierre-Yves Rochon's interiors favour cream, blue, classical furniture and substantial bathrooms. The palette is refined rather than adventurous, leaving restaurants, flowers and views to supply drama. Families benefit from connecting options and a service culture equipped for complicated itineraries; design pilgrims may prefer a smaller, more authored Paris address."
    ]},
    { heading: "Six Michelin stars under one roof", body: [
      "The current dining constellation is exceptional: Christian Le Squer's Le Cinq holds three Michelin stars; L'Orangerie holds two; Simone Zanoni's Mediterranean Le George holds one. La Galerie and Le Bar handle the less ceremonial appetite. This makes the hotel a gastronomic destination—and can make a stay feel scheduled around lengthy meals.",
      "Choose one ambitious dinner. The spa's 17-metre pool, vitality pool and treatment rooms then become useful recovery, not decorative wellness. George V is strongest for travellers who value restaurant access, room size and an operation practised at solving high-stakes requests. Those seeking bohemian Paris or discreet small-scale charm should let it remain a very good place to dine."
    ]}
  ],
  "bulgari-resort-dubai": [
    { heading: "A Mediterranean proposition on Jumeira Bay", body: [
      "Bulgari sits on the seahorse-shaped Jumeira Bay island, physically close to central Dubai and psychologically removed from its towers. Antonio Citterio Patricia Viel's low architecture uses limestone, dark timber, bronze and framed gardens to evoke an Italian resort without copying one. The Burj Khalifa remains visible from parts of the property, a reminder that this calm is carefully constructed within a city.",
      "The inventory includes 101 rooms and suites plus 20 villas, unusually low-density by Dubai standards. Sea-view rooms, skyline orientations and private-pool villas create different experiences. A villa buys space and concealment but can place guests farther from restaurants; a well-positioned room keeps the marina and social life close."
    ]},
    { heading: "Hotel, beach and yacht club", body: [
      "The resort beach is compact rather than an endless natural shoreline, while the main pool supplies the polished day. Across the marina, the Yacht Club has its own jewel-toned pool, 46-berth harbour, restaurant, lounge and children's club. Access conditions differ for hotel guests and members and should be checked; seeing the facility does not automatically include every cabana.",
      "The marina promenade gives evening movement to a property that might otherwise become too hushed. It also attracts diners and members from outside. Guests seeking absolute resort privacy should choose room and villa position carefully. Those who enjoy watching a social world assemble around boats will understand the design immediately."
    ]},
    { heading: "Italian dining in Gulf light", body: [
      "Il Ristorante–Niko Romito is the gastronomic anchor, Hōseki offers an intimate Japanese counter and the Yacht Club focuses on Italian seafood. La Terrazza has recently carried pizza by Pier Daniele Seu alongside all-day Mediterranean habits. Concepts and seasonal schedules evolve, so old references to Il Caffè should be checked against the current date.",
      "The Bulgari premium buys materials, low density and a notably restrained alternative to Dubai maximalism. It does not buy walkability beyond the island, and transfers to old Dubai, desert or distant beaches still meet traffic. Book for a short urban-resort pause, design and dining. Travellers wanting water slides, vast beaches or overt spectacle have stronger choices elsewhere."
    ]}
  ],
  "upper-house-hong-kong": [
    { heading: "A hotel that begins above the hotel", body: [
      "Upper House rises from Pacific Place in Admiralty, with no conventional lobby at street level. Guests move upward through André Fu's stone, timber and sculptural spaces until Hong Kong opens around them. The absence of counters and chandeliers was radical when the hotel opened and remains its defining gesture: service approaches like hosting in a residence, not processing at a palace.",
      "Pacific Place provides direct shopping and transport convenience, but Admiralty is more business nexus than neighbourhood. Wan Chai, Central and the hills are close; the waterfront requires navigating roads and elevated routes. The hotel works brilliantly for appointments across Hong Kong Island and less naturally for travellers who want a lane of bars immediately outside."
    ]},
    { heading: "Studios large enough to live in", body: [
      "The entry Studio 70 begins at roughly 70 square metres, already larger than many city suites, with a limestone bath positioned against the view, separate dressing and a complimentary Maxi Bar. Studio 80 categories add space and varying mountain, city or harbour outlooks. The room's long plan makes light and orientation more important than another ten square metres.",
      "Upper Suites add a genuine living area; the 182-square-metre André Fu Suite is a refined retrospective of the designer's relationship with the house. None requires ornamental overstatement. Families should confirm connecting possibilities early; couples should spend on view before scale. In Hong Kong, a bath above the moving city is the amenity that survives memory."
    ]},
    { heading: "One restaurant, several quieter rooms", body: [
      "Salisterra occupies level 49 with Mediterranean menus, harbour views and a bar running from breakfast into late evening; Ricardo Chaneton currently advises the food. The Green Room offers a smaller cocktail setting, while The Lawn and Tea Room provide alternatives when open. This is not a multi-restaurant resort, and that limitation encourages the correct behaviour: eat across Hong Kong.",
      "Wellness relies on in-room treatments, visiting practitioners and curated programmes rather than a vast basement spa or swimming pool. Guests who require a pool should note the absence before booking. Upper House excels through space, calm and human service; it is less suited to travellers who measure luxury by facilities or prefer a formal lobby announcing their arrival."
    ]}
  ],
  "hopewell-hotel-hong-kong": [
    { heading: "A thousand-room vertical city", body: [
      "Hopewell Hotel is one of Hong Kong's largest new luxury hotels, with 1,000 rooms rising above Kennedy Road in Wan Chai and connected to the expanding Hopewell Mall. Its scale creates convention capacity and family-friendly inventory rather than boutique intimacy. Lifts, breakfast peaks and events shape the day; efficient wayfinding is more important than a theatrical lobby.",
      "The hillside address sits above Wan Chai's traditional street grid. New pedestrian connections improve access, but the climb and multi-level mall environment can confuse first arrivals. The position is practical for Admiralty, Wan Chai and Happy Valley; Kowloon plans require MTR or harbour crossings."
    ]},
    { heading: "Height determines the view", body: [
      "Deluxe Rooms begin at 30 square metres with hillside views. Premium City Rooms expand to 38 square metres on levels 24 to 41; Panoramic categories occupy levels 42 to 50 with partial harbour aspects; full Premium Harbour Rooms rise to levels 51 to 55. The naming is unusually literal, making floor and orientation the real upgrade.",
      "Suites range from 51 to 112 square metres, with high-floor two-bedroom Wan Chai East and West layouts aimed at families or longer stays. Connecting rooms are a strength in a city where family inventory is often tight. Ask whether the bathroom has a tub—some room types are shower-only—and whether laundry equipment applies only to extended bookings."
    ]},
    { heading: "Who should choose it", body: [
      "Hopewell is best approached as a modern, high-capacity base: bright rooms, extensive meeting space, mall convenience and views improving sharply with height. It does not offer the established service mythology of the Peninsula or the residential design intimacy of Upper House. Rates should reflect that distinction, especially while the surrounding complex continues to mature.",
      "Families, business groups and travellers needing large connecting inventory will find practical advantages. Couples seeking a singular Hong Kong hotel story may prefer a smaller address. Book a high harbour category only when the view matters enough to justify it; lower hillside rooms can provide calmer sleep and preserve the budget for the city."
    ]}
  ]
};
